# ── Nó: validar_conformidade ─────────────────────────────────────────────────

def validar_conformidade(state: AuditState) -> dict:
    """
    Aplica as regras de negócio determinísticas após a análise vision.

    Regras gerais: legível, data visível, assinatura presente.
    CPF:  assinatura completa (rubricas não aceitas).
    CNPJ: carimbo obrigatório; terceiro pagador validado.
    """
    motivos = []

    # ── Comprovante não encontrado: arquivo físico ausente ────────────────
    path = state.get("comprovante_path")
    if not path or not Path(str(path)).exists():
        motivos.append("Comprovante não encontrado")
        logger.info(
            f"validar_conformidade: {state['current_cte']} "
            f"→ RECUSADO (comprovante não encontrado)"
        )
        return {"aprovado": False, "motivos_recusa": motivos}

    # ── Ilegível: único motivo, não avalia demais campos ─────────────────
    if not state.get("legivel"):
        motivos.append(
            "Comprovante ilegível: informações de identificação não legíveis"
        )
        aprovado = False
        logger.info(
            f"validar_conformidade: {state['current_cte']} "
            f"→ RECUSADO (ilegível) | motivos={motivos}"
        )
        return {"aprovado": aprovado, "motivos_recusa": motivos}

    if not state.get("data_visivel"):
        motivos.append("Data de recebimento não visível")
    if not state.get("assinatura_presente"):
        motivos.append("Assinatura ausente")

    tipo = state.get("tipo_recebedor", "indefinido")

    if tipo == "CPF":
        # "rubrica" é rejeitada; "extensa"/"completa" são aceitas
        if state.get("tipo_assinatura") == "rubrica":
            motivos.append(
                "CPF: rubrica não aceita"
                " — necessária assinatura por extenso"
            )
    elif tipo == "CNPJ":
        if not state.get("carimbo_presente"):
            motivos.append("CNPJ: carimbo da empresa ausente")
        if (
            state.get("terceiro_pagador")
            and not state.get("carimbo_presente")
        ):
            motivos.append("CNPJ: terceiro pagador não validado")
    elif tipo == "indefinido":
        motivos.append(
            "Tipo de recebedor não identificado (CPF/CNPJ)"
        )

    aprovado = len(motivos) == 0
    status = "APROVADO" if aprovado else "RECUSADO"
    logger.info(
        f"validar_conformidade: {state['current_cte']} "
        f"→ {status} | motivos={motivos}"
    )
    return {"aprovado": aprovado, "motivos_recusa": motivos}


# ── Nó: executar_acoes_recusa ────────────────────────────────────────────────

def executar_acoes_recusa(state: AuditState) -> dict:
    """
    Executa as ações obrigatórias em caso de recusa:

    1. WhatsApp para a unidade com CTE + motivos
    2. SSW ocorrência 047
    3. MTZ bloqueio de comissão
